import AppKit
import AVFoundation
import Darwin
import Foundation

/// Generated bytes and injected slow system calls only; no user media or mounts.
private final class PreviewIOGate: @unchecked Sendable {
    let entered = DispatchSemaphore(value: 0)
    let resume = DispatchSemaphore(value: 0)
    let closed = DispatchSemaphore(value: 0)
    private let lock = NSLock()
    private var storedFD: Int32 = -1
    private var readReturned = false
    private var closes = 0
    var descriptor: Int32 { lock.lock(); defer { lock.unlock() }; return storedFD }
    var closeCount: Int { lock.lock(); defer { lock.unlock() }; return closes }
    func read(_ descriptor: Int32, _ pointer: UnsafeMutableRawPointer, _ count: Int, _ offset: off_t) -> Int {
        precondition(!Thread.isMainThread)
        lock.lock(); storedFD = descriptor; lock.unlock()
        entered.signal()
        precondition(resume.wait(timeout: .now() + 5) == .success)
        let result = Darwin.pread(descriptor, pointer, count, offset)
        lock.lock(); readReturned = true; lock.unlock()
        return result
    }
    func finishRead(_ descriptor: Int32) {
        precondition(!Thread.isMainThread)
        lock.lock()
        precondition(readReturned, "A blocked reader must retain its descriptor until its syscall finishes")
        closes += 1
        lock.unlock()
        _ = Darwin.close(descriptor)
        closed.signal()
    }
}

private final class PreviewCloseGate: @unchecked Sendable {
    let entered = DispatchSemaphore(value: 0)
    let resume = DispatchSemaphore(value: 0)
    let closed = DispatchSemaphore(value: 0)
    private let lock = NSLock()
    private var closes = 0
    var closeCount: Int { lock.lock(); defer { lock.unlock() }; return closes }
    func close(_ descriptor: Int32) {
        precondition(!Thread.isMainThread, "A remote close must never run on AppKit")
        lock.lock(); closes += 1; lock.unlock()
        entered.signal()
        precondition(resume.wait(timeout: .now() + 5) == .success)
        _ = Darwin.close(descriptor)
        closed.signal()
    }
}

private final class PreviewReadPoolGate: @unchecked Sendable {
    let resume = DispatchSemaphore(value: 0)
    private let lock = NSLock()
    private var active = Set<Int32>()
    private var peak = 0
    private var started = 0
    private var closes: [Int32: Int] = [:]
    var snapshot: (active: Set<Int32>, peak: Int, started: Int, closes: [Int32: Int]) {
        lock.lock(); defer { lock.unlock() }
        return (active, peak, started, closes)
    }
    func read(_ descriptor: Int32, _ pointer: UnsafeMutableRawPointer, _ count: Int, _ offset: off_t) -> Int {
        precondition(!Thread.isMainThread)
        lock.lock()
        precondition(active.insert(descriptor).inserted, "A loader must have only one active reader")
        started += 1; peak = max(peak, active.count)
        lock.unlock()
        precondition(resume.wait(timeout: .now() + 5) == .success)
        let result = Darwin.pread(descriptor, pointer, count, offset)
        lock.lock(); active.remove(descriptor); lock.unlock()
        return result
    }
    func close(_ descriptor: Int32) {
        precondition(!Thread.isMainThread)
        lock.lock()
        precondition(!active.contains(descriptor), "An active syscall still owns its descriptor")
        closes[descriptor, default: 0] += 1
        lock.unlock()
        _ = Darwin.close(descriptor)
    }
}

@main @MainActor struct FilePreviewLifecycleTests {
    static func signal(_ semaphore: DispatchSemaphore) async {
        let succeeded = await Task.detached { semaphore.wait(timeout: .now() + 5) == .success }.value
        precondition(succeeded, "Generated I/O gate timed out")
    }
    static func until(_ condition: () -> Bool) async {
        let deadline = Date().addingTimeInterval(5)
        while !condition(), Date() < deadline { try? await Task.sleep(nanoseconds: 5_000_000) }
        precondition(condition(), "Generated cleanup did not finish")
    }
    static func main() async throws {
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("MyCloudDriver-PreviewLifecycle-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let source = directory.appendingPathComponent("generated.bin")
        try Data(repeating: 0x41, count: 4096).write(to: source)

        // Hold close itself after invalidation: status, selection and cancellation
        // must stay usable, and repeated invalidation must not close a reused FD.
        let closeGate = PreviewCloseGate()
        var loader: FilePreviewResourceLoader? = try FilePreviewResourceLoader(fileURL: source, blockSize: 1024,
            io: .init(close: { closeGate.close($0) }))
        let began = ProcessInfo.processInfo.systemUptime
        loader!.invalidate()
        precondition(ProcessInfo.processInfo.systemUptime - began < 0.2)
        await signal(closeGate.entered)
        precondition(loader!.status.cache.cachedBytes == 0 && loader!.snapshot.cachedBytes == 0)
        var heartbeat = false
        let pulse = Task { @MainActor in heartbeat = true }
        await pulse.value
        precondition(heartbeat)
        for _ in 0..<50 { precondition(loader!.status.cache.cachedBytes == 0) }
        loader!.invalidate(); loader = nil
        precondition(closeGate.closeCount == 1)
        closeGate.resume.signal(); await signal(closeGate.closed)
        print("PASS slow close runs off AppKit without holding loader locks; FD ownership transfers once")

        // Cancellation releases the awaiting preview while a pread ignores it.
        // The descriptor remains open until that exact read returns.
        let readGate = PreviewIOGate()
        let blocked = try FilePreviewResourceLoader(fileURL: source, blockSize: 1024,
            io: .init(read: { readGate.read($0, $1, $2, $3) }, close: { readGate.finishRead($0) }))
        let priming = Task { try await blocked.prime(headBlocks: 1, tailBlocks: 0) { _ in } }
        await signal(readGate.entered)
        let originalFD = readGate.descriptor
        precondition(fcntl(originalFD, F_GETFD) >= 0)
        let cancelledAt = ProcessInfo.processInfo.systemUptime
        priming.cancel()
        do { try await priming.value; preconditionFailure("Cancelled priming must stop") }
        catch { precondition(error is CancellationError) }
        precondition(ProcessInfo.processInfo.systemUptime - cancelledAt < 0.2)
        precondition(readGate.closeCount == 0 && fcntl(originalFD, F_GETFD) >= 0)
        precondition(blocked.snapshot.cachedBytes == 0)
        let another = try FileHandle(forReadingFrom: source)
        precondition(another.fileDescriptor != originalFD, "An in-flight read's descriptor cannot be reused")
        try another.close()
        readGate.resume.signal(); await signal(readGate.closed)
        precondition(blocked.snapshot.cachedBytes == 0 && readGate.closeCount == 1,
            "Late read completion must not repopulate an invalidated cache")
        print("PASS cancellation is prompt, active read retains its FD, and late bytes never restore the cache")

        let stalledGate = PreviewIOGate()
        let stalled = try FilePreviewResourceLoader(fileURL: source, blockSize: 1024,
            io: .init(read: { stalledGate.read($0, $1, $2, $3) }, close: { stalledGate.finishRead($0) }))
        let timeoutAt = ProcessInfo.processInfo.systemUptime
        let stalledPriming = Task { try await stalled.prime(headBlocks: 1, tailBlocks: 0, noProgressTimeout: 0.2) { _ in } }
        await signal(stalledGate.entered)
        do {
            try await stalledPriming.value
            preconditionFailure("A stalled read must reach its no-progress deadline")
        } catch { precondition(error is FilePreviewReadTimeout) }
        precondition(ProcessInfo.processInfo.systemUptime - timeoutAt < 1)
        precondition(stalled.failure is FilePreviewReadTimeout && stalled.status.failed && stalled.status.bytesPerSecond == 0)
        precondition(stalled.snapshot.cachedBytes == 0 && stalledGate.closeCount == 0)
        stalledGate.resume.signal(); await signal(stalledGate.closed)
        print("PASS a stalled prime reports a typed read timeout and waits safely for the outstanding syscall")

        // Eight short reads take longer than the deadline in total. Each real
        // byte advance renews it before a complete block becomes available.
        let advancing = try FilePreviewResourceLoader(fileURL: source, blockSize: 1024,
            io: .init(read: { descriptor, pointer, count, offset in
                precondition(!Thread.isMainThread)
                Thread.sleep(forTimeInterval: 0.04)
                return Darwin.pread(descriptor, pointer, min(count, 128), offset)
            }))
        let advancingAt = ProcessInfo.processInfo.systemUptime
        try await advancing.prime(headBlocks: 1, tailBlocks: 0, noProgressTimeout: 0.15) { _ in }
        precondition(ProcessInfo.processInfo.systemUptime - advancingAt > 0.15)
        precondition(advancing.status.bytesRead == 1024 && !advancing.status.failed)
        advancing.invalidate()
        print("PASS partial-block byte progress renews the deadline without imposing a total download limit")

        // Old previews can stay inside pread after cancellation. Shared workers
        // cap those syscalls, while queued stale turns close without ever reading.
        let pool = PreviewReadPoolGate(), limit = FilePreviewResourceLoader.maximumConcurrentReads
        let total = limit * 3
        var pooled = try (0..<total).map { _ in
            try FilePreviewResourceLoader(fileURL: source, blockSize: 1024,
                io: .init(read: { pool.read($0, $1, $2, $3) }, close: { pool.close($0) }))
        }
        let pooledPriming = pooled.map { loader in
            Task { try await loader.prime(headBlocks: 1, tailBlocks: 0) { _ in } }
        }
        await until { pool.snapshot.active.count == limit }
        // Allow every other prime to queue behind the deliberately held reads.
        try await Task.sleep(nanoseconds: 50_000_000)
        precondition(pool.snapshot.started == limit && pool.snapshot.peak == limit)
        let poolCancelAt = ProcessInfo.processInfo.systemUptime
        pooledPriming.forEach { $0.cancel() }
        for loader in pooled { loader.invalidate(); loader.invalidate() }
        for prime in pooledPriming {
            do { try await prime.value; preconditionFailure("All generated primes must cancel") }
            catch { precondition(error is CancellationError) }
        }
        precondition(ProcessInfo.processInfo.systemUptime - poolCancelAt < 0.5)
        await until { pool.snapshot.closes.count == total - limit }
        let held = pool.snapshot
        precondition(held.active.count == limit && held.started == limit,
            "Queued invalidated readers must close without waiting for a shared worker or executing I/O")
        for descriptor in held.active { precondition(fcntl(descriptor, F_GETFD) >= 0) }
        for _ in 0..<limit { pool.resume.signal() }
        await until { pool.snapshot.closes.count == total }
        pooled.removeAll()
        let finished = pool.snapshot
        precondition(finished.active.isEmpty && finished.peak == limit && finished.started == limit)
        precondition(finished.closes.values.allSatisfy { $0 == 1 }, "Each queued or active FD must close exactly once")
        print("PASS shared readers cap stalled syscalls, skip cancelled queued I/O, and close every FD once")

        // Occupy both cleanup workers to prove releasing a generated copy only
        // enqueues deletion. Its separate source is never owned by that cleanup.
        let cleanupEntered = DispatchSemaphore(value: 0), cleanupResume = DispatchSemaphore(value: 0)
        for _ in 0..<2 {
            NativeFileWork.performCleanup {
                precondition(!Thread.isMainThread)
                cleanupEntered.signal()
                precondition(cleanupResume.wait(timeout: .now() + 5) == .success)
            }
        }
        await signal(cleanupEntered); await signal(cleanupEntered)
        let generated = directory.appendingPathComponent("owned-copy")
        try FileManager.default.createDirectory(at: generated, withIntermediateDirectories: false)
        let output = generated.appendingPathComponent("generated.mp4")
        try Data(repeating: 0x42, count: 8192).write(to: output)
        var copy: VideoPreviewCopy? = VideoPreviewCopy(url: output, directory: generated)
        precondition(copy!.url == output)
        let releaseAt = ProcessInfo.processInfo.systemUptime
        copy = nil
        precondition(ProcessInfo.processInfo.systemUptime - releaseAt < 0.2)
        precondition(FileManager.default.fileExists(atPath: output.path))
        cleanupResume.signal(); cleanupResume.signal()
        await until { !FileManager.default.fileExists(atPath: generated.path) }
        let preserved = try Data(contentsOf: source)
        precondition(preserved == Data(repeating: 0x41, count: 4096))
        print("PASS generated-copy release defers deletion and preserves the original")
    }
}
